import React from "react";
import "./Services.css";

export default function Services() {
  const services = [
    { name: "Electrician", img: "https://images.unsplash.com/photo-1581090464777-1c3f1a06c13b" },
    { name: "Plumber", img: "https://images.unsplash.com/photo-1581579185169-1cdb59d7d77b" },
    { name: "Carpenter", img: "https://images.unsplash.com/photo-1503387762-592deb58ef4e" },
    { name: "House Cleaning", img: "https://images.unsplash.com/photo-1581579185169-1cdb59d7d77b" },
    { name: "AC Repair", img: "https://images.unsplash.com/photo-1597007068213-5f3c2d7cb6aa" },
    { name: "Painting", img: "https://images.unsplash.com/photo-1503387762-592deb58ef4e" },
    { name: "Beauty & Salon", img: "https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9" },
    { name: "Massage Service", img: "https://images.unsplash.com/photo-1556228453-efd6c1ff04f0" },
    { name: "Pest Control", img: "https://images.unsplash.com/photo-1581579185169-1cdb59d7d77b" },
    { name: "Appliance Repair", img: "https://images.unsplash.com/photo-1581091215367-59ab6b1e39f4" },
    { name: "Laundry", img: "https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9" },
    { name: "Gardening", img: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6" },
    { name: "Chef / Cooking", img: "https://images.unsplash.com/photo-1556912173-3bb406ef7a36" },
    { name: "Driver on Call", img: "https://images.unsplash.com/photo-1517849845537-4d257902454a" },
    { name: "Computer Repair", img: "https://images.unsplash.com/photo-1517336714731-489689fd1ca8" },
  ];

  return (
    <div className="services-container">
      <h1>Our Services</h1>

      <div className="services-grid">
        {services.map((service, index) => (
          <div className="service-card" key={index}>
            <img src={service.img} alt={service.name} />
            <h3>{service.name}</h3>
          </div>
        ))}
      </div>
    </div>
  );
}
